function emailHtml({preheader='',title,text,buttonLabel,buttonUrl,details=[],note='',qrCodeBase64='',copyCode=''}){const rows=details.map(([label,value])=>`<tr><td style="padding:9px 0;color:#85a9c4">${escapeHtml(label)}</td><td style="padding:9px 0;text-align:right;color:#eefaff;font-weight:700">${escapeHtml(value)}</td></tr>`).join(''),safeQr=/^[A-Za-z0-9+/=]+$/.test(String(qrCodeBase64||''))?String(qrCodeBase64):'',qr=safeQr?`<div style="margin:24px 0;text-align:center"><div style="display:inline-block;padding:12px;background:#fff;border-radius:16px"><img src="data:image/png;base64,${safeQr}" width="220" height="220" alt="QR Code Pix" style="display:block;width:220px;height:220px"></div><p style="margin:10px 0 0;color:#85a9c4;font-size:12px">Escaneie o QR Code no aplicativo do seu banco.</p></div>`:'',copy=copyCode?`<div style="margin:22px 0;padding:16px;border:1px solid #1d5675;border-radius:12px;background:#061725"><strong style="display:block;margin-bottom:8px;color:#71e9ff">Pix copia e cola</strong><div style="word-break:break-all;color:#d9eef8;font-family:monospace;font-size:12px;line-height:1.6">${escapeHtml(copyCode)}</div></div>`:'';return `<!doctype html><html><body style="margin:0;background:#030b14;font-family:Arial,sans-serif;color:#eefaff"><div style="display:none;max-height:0;overflow:hidden">${escapeHtml(preheader)}</div><table width="100%" cellspacing="0" cellpadding="0" style="background:#030b14;padding:34px 14px"><tr><td align="center"><table width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;background:linear-gradient(145deg,#0e2940,#071522);border:1px solid #2176a1;border-radius:20px;overflow:hidden"><tr><td style="padding:30px 34px;border-bottom:1px solid #1d4965"><div style="color:#63e8ff;font-size:12px;letter-spacing:2px;font-weight:800">ICE OPTIMIZER · POR MACIOTA</div><h1 style="margin:12px 0 0;font-size:28px;color:#fff">${escapeHtml(title)}</h1></td></tr><tr><td style="padding:30px 34px"><p style="margin:0 0 22px;color:#b8d2e5;line-height:1.7;font-size:16px">${escapeHtml(text)}</p>${rows?`<table width="100%" cellspacing="0" cellpadding="0" style="border-top:1px solid #1b4965;border-bottom:1px solid #1b4965;margin:20px 0">${rows}</table>`:''}${qr}${copy}${buttonLabel&&buttonUrl?`<p style="margin:26px 0"><a href="${escapeHtml(buttonUrl)}" style="display:inline-block;background:linear-gradient(135deg,#46e7f5,#1478ff);color:#04111c;text-decoration:none;padding:14px 22px;border-radius:10px;font-weight:800">${escapeHtml(buttonLabel)}</a></p>`:''}${note?`<p style="margin:22px 0 0;color:#799ab1;font-size:13px;line-height:1.6">${escapeHtml(note)}</p>`:''}</td></tr><tr><td style="padding:18px 34px;background:#06111d;color:#6f92aa;font-size:12px">Mensagem automática de segurança e serviço do Ice Optimizer.</td></tr></table></td></tr></table></body></html>`}
async function sendEmail(message){if(!RESEND_API_KEY||!message.to)return {ok:false,skipped:true};const payload={from:EMAIL_FROM,to:[message.to],subject:message.subject,html:emailHtml(message)};if(EMAIL_REPLY_TO)payload.reply_to=EMAIL_REPLY_TO;const response=await fetch('https://api.resend.com/emails',{method:'POST',signal:AbortSignal.timeout(8000),headers:{authorization:'Bearer '+RESEND_API_KEY,'content-type':'application/json','idempotency-key':String(message.idempotencyKey||crypto.randomUUID()).slice(0,256)},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw Error(data.message||'Falha ao enviar e-mail.');return {ok:true,id:data.id}}
async function trackedEmail(db,message){try{const result=await sendEmail(message);if(result.ok){console.log('E-mail enviado:',message.template,message.to);db.events.unshift({at:new Date().toISOString(),type:'email_sent',template:message.template,to:message.to,emailId:result.id})}else if(result.skipped){console.error('E-mail não enviado:',message.template,'RESEND_API_KEY ou destinatário ausente');db.events.unshift({at:new Date().toISOString(),type:'email_skipped',template:message.template,to:message.to||'',message:'RESEND_API_KEY ou destinatário ausente'})}return result}catch(error){console.error('E-mail não enviado:',message.template,error.message);db.events.unshift({at:new Date().toISOString(),type:'email_failed',template:message.template,to:message.to,message:error.message});return {ok:false,error:error.message}}}
function blank(){return {licenses:[],events:[],users:[],orders:[],partners:[],withdrawals:[],supportMessages:[]}}
function load(){try{const db=JSON.parse(fs.readFileSync(DATA,'utf8'));for(const k of Object.keys(blank()))db[k]||=[];return db}catch{return blank()}}
function save(db){fs.mkdirSync(path.dirname(DATA),{recursive:true});const tmp=DATA+'.tmp';fs.writeFileSync(tmp,JSON.stringify(db,null,2));fs.renameSync(tmp,DATA)}
function json(res,status,data,headers={}){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',...headers});res.end(JSON.stringify(data))}
function body(req){return new Promise((resolve,reject)=>{let data='';req.on('data',c=>{data+=c;if(data.length>250000){reject(Error('too-large'));req.destroy()}});req.on('end',()=>{try{resolve(data?JSON.parse(data):{})}catch{reject(Error('invalid-json'))}});req.on('error',reject)})}
function cookies(req){return Object.fromEntries((req.headers.cookie||'').split(';').map(x=>x.trim().split('=')).filter(x=>x.length===2))}
function session(req){const raw=cookies(req).ice_admin;if(!raw)return false;const [exp,sig]=raw.split('.');return Number(exp)>Date.now()&&safe(sig,hmac(exp))}
function csrf(req){return safe(req.headers['x-csrf-token'],hmac((cookies(req).ice_admin||'')+'csrf').slice(0,32))}
