function duration(plan){return {d30:30,d90:90,d180:180,d365:365,permanent:null}[plan]}
function activatePlan(db,user,plan,source,orderId){const days=duration(plan);if(days===undefined)return null;const now=new Date(),current=licenseFor(db,user),license=current||{id:crypto.randomUUID(),userId:user.id,createdAt:now.toISOString()};license.plan=plan;license.revoked=false;license.activatedAt=now.toISOString();license.expiresAt=days?new Date(now.getTime()+days*86400000).toISOString():null;license.source=source||'admin';if(orderId)license.orderId=orderId;if(!current)db.licenses.unshift(license);user.licenseId=license.id;return license}
function setCustomerPlan(db,user,input){if(!user)return {status:404,data:{ok:false,message:'Cliente não encontrado.'}};const plan=String(input.plan||'none'),premiumSupport=!!input.premiumSupport,allowed=['none','d30','d90','d180','d365','permanent'];if(!allowed.includes(plan))return {status:400,data:{ok:false,message:'Plano inválido.'}};const previous=licenseFor(db,user),previousPlan=previous&&previous.plan||'none',now=new Date().toISOString();if(plan==='none'){if(previous)db.licenses=db.licenses.filter(x=>x.id!==previous.id);delete user.licenseId;db.events.unshift({at:now,type:'admin_plan_changed',user:user.id,from:previousPlan,to:'none',premiumSupport:false});return {status:200,data:{ok:true,customer:publicCustomer(user,db)}}}const license=activatePlan(db,user,plan,'admin');if(!license)return {status:400,data:{ok:false,message:'Plano inválido.'}};license.premiumSupport=premiumSupport;if(premiumSupport)license.premiumSupportAt=now;else{delete license.premiumSupportAt;delete license.premiumSupportOrderId}db.events.unshift({at:now,type:'admin_plan_changed',user:user.id,from:previousPlan,to:plan,premiumSupport});return {status:200,data:{ok:true,customer:publicCustomer(user,db)}}}

function passwordHash(password,salt){return crypto.scryptSync(password,salt,32).toString('hex')}
