function bearer(req){return String(req.headers.authorization||'').replace(/^Bearer\s+/i,'')}
function licenseFor(db,user){return user&&db.licenses.find(x=>x.id===user.licenseId)}
function licenseStatus(l){return !l?'pending':l.revoked?'revoked':l.expiresAt&&Date.parse(l.expiresAt)<=Date.now()?'expired':'active'}
function publicAccount(user,license,token,supportUnread=0,partner=null){return {ok:true,token,username:user.username,email:user.email||'',plan:license&&license.plan||'none',status:licenseStatus(license),expiresAt:license&&license.expiresAt||null,permanent:!!license&&!license.expiresAt,createdAt:user.createdAt,hardwareBound:!!(license&&license.hardwareHash),lastSeenAt:license&&license.lastSeenAt||null,premiumSupport:!!(license&&license.premiumSupport),supportUnread:Number(supportUnread||0),partner:!!(partner&&partner.status==='active'),partnerSlug:partner&&partner.status==='active'?partner.slug:''}}
function validateCredentials(input){const username=String(input.username||'').trim(),email=String(input.email||'').trim().toLowerCase(),password=String(input.password||'');if(!/^[a-zA-Z0-9._-]{3,24}$/.test(username))return {error:'Use de 3 a 24 caracteres no usuário.'};if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return {error:'Informe um e-mail válido.'};if(password.length<8||password.length>128)return {error:'A senha precisa ter pelo menos 8 caracteres.'};return {username,email,password}}
function createAccount(db,input){const v=validateCredentials(input);if(v.error)return {status:400,data:{ok:false,message:v.error}};if(db.users.some(x=>x.usernameLower===v.username.toLowerCase()))return {status:409,data:{ok:false,message:'Este usuário já existe.'}};if(v.email&&db.users.some(x=>x.email===v.email))return {status:409,data:{ok:false,message:'Este e-mail já está cadastrado.'}};const salt=crypto.randomBytes(16).toString('hex'),user={id:crypto.randomUUID(),username:v.username,usernameLower:v.username.toLowerCase(),email:v.email,passwordSalt:salt,passwordHash:passwordHash(v.password,salt),createdAt:new Date().toISOString()};db.users.unshift(user);db.events.unshift({at:user.createdAt,type:'customer_created',user:user.id});return {status:201,data:publicAccount(user,null,issueToken(user,'web'))}}
function createPasswordReset(db,email){const normalized=String(email||'').trim().toLowerCase(),user=db.users.find(x=>x.email===normalized);if(!user)return {user:null,token:null};const token=crypto.randomBytes(32).toString('base64url');user.passwordResetHash=sha(token);user.passwordResetExpiresAt=new Date(Date.now()+30*60000).toISOString();db.events.unshift({at:new Date().toISOString(),type:'password_reset_requested',user:user.id});return {user,token}}
function resetPassword(db,input){const token=String(input.token||''),password=String(input.password||''),user=db.users.find(x=>x.passwordResetHash&&safe(x.passwordResetHash,sha(token)));if(!user||!user.passwordResetExpiresAt||Date.parse(user.passwordResetExpiresAt)<Date.now())return {status:400,data:{ok:false,message:'Este link expirou ou já foi utilizado.'}};if(password.length<8||password.length>128)return {status:400,data:{ok:false,message:'A senha precisa ter pelo menos 8 caracteres.'}};const salt=crypto.randomBytes(16).toString('hex');user.passwordSalt=salt;user.passwordHash=passwordHash(password,salt);delete user.passwordResetHash;delete user.passwordResetExpiresAt;delete user.webTokenHash;delete user.tokenHash;user.passwordChangedAt=new Date().toISOString();db.events.unshift({at:user.passwordChangedAt,type:'password_changed',user:user.id});return {status:200,data:{ok:true,message:'Senha alterada com sucesso. Você já pode entrar novamente.'},user}}
function changePassword(db,user,input){const current=String(input.currentPassword||''),password=String(input.newPassword||'');if(!safe(passwordHash(current,user.passwordSalt||''),user.passwordHash))return {status:401,data:{ok:false,message:'A senha atual está incorreta.'}};if(password.length<8||password.length>128)return {status:400,data:{ok:false,message:'A nova senha precisa ter pelo menos 8 caracteres.'}};if(current===password)return {status:400,data:{ok:false,message:'Escolha uma senha diferente da atual.'}};const salt=crypto.randomBytes(16).toString('hex');user.passwordSalt=salt;user.passwordHash=passwordHash(password,salt);delete user.tokenHash;user.passwordChangedAt=new Date().toISOString();const token=issueToken(user,'web');db.events.unshift({at:user.passwordChangedAt,type:'password_changed',user:user.id});return {status:200,data:{ok:true,token,message:'Senha alterada com sucesso.'},user}}
function accountEmail(user){return {to:user.email,subject:'Sua conta Ice Optimizer foi criada',template:'account_created',idempotencyKey:'account-created-'+user.id,preheader:'Sua conta está pronta.',title:'Bem-vindo ao Ice Optimizer',text:`Olá, ${user.username}. Sua conta foi criada com segurança. Agora você pode escolher um plano e concluir o pagamento pelo site.`,buttonLabel:'Acessar minha conta',buttonUrl:PUBLIC_URL||'https://iceotimizacoes.store',details:[['Usuário',user.username],['Status','Aguardando ativação']],note:'Nunca enviaremos sua senha por e-mail.'}}
