function checkPassword(db,input){const login=String(input.login||input.username||input.email||'').trim().toLowerCase(),user=db.users.find(x=>x.usernameLower===login||String(x.email||'').toLowerCase()===login),password=String(input.password||'');if(!user||!safe(passwordHash(password,user.passwordSalt||''),user.passwordHash))return null;return user}
