function webProfile(db,token){const user=db.users.find(x=>x.webTokenHash&&safe(x.webTokenHash,sha(token||'')));if(!user)return {status:401,data:{ok:false,message:'Sessão expirada.'}};const unread=(db.supportMessages||[]).filter(x=>x.userId===user.id&&x.sender==='admin'&&!x.readByCustomer).length;return {status:200,data:publicAccount(user,licenseFor(db,user),null,unread,partnerForUser(db,user)),user}}
function simulatePurchase(db,token,plan){const auth=webProfile(db,token);if(auth.status!==200)return auth;if(duration(plan)===undefined)return {status:400,data:{ok:false,message:'Plano inválido.'}};const user=auth.user,license=activatePlan(db,user,plan,'simulation');db.events.unshift({at:new Date().toISOString(),type:'purchase_simulated',user:user.id,plan});return {status:200,data:{...publicAccount(user,license,null),simulated:true,download:'https://raw.githubusercontent.com/kaiquedupix-max/iceoptmizer/main/downloads/ice-optimizer.exe'}}}
function hardwareAllowed(license,input,bind=false){const device=String(input.deviceId||''),hardware=String(input.hardwareId||device);if(!hardware)return false;if(!license.hardwareHash&&bind){license.deviceHash=sha(device);license.hardwareHash=sha(hardware);license.hardwareBoundAt=new Date().toISOString();return true}return !!license.hardwareHash&&safe(license.hardwareHash,sha(hardware))}
function loginAccount(db,input){const user=checkPassword(db,input);if(!user)return {status:401,data:{ok:false,message:'Usuário ou senha incorretos.'}};const license=licenseFor(db,user),status=licenseStatus(license);if(status==='pending')return {status:402,data:{ok:false,message:'Sua conta ainda não possui uma ativação. Entre no site e finalize a compra de um plano.'}};if(status==='revoked')return {status:403,data:{ok:false,message:'A ativação desta conta foi suspensa.'}};if(status==='expired')return {status:403,data:{ok:false,message:'Sua ativação expirou.'}};if(!hardwareAllowed(license,input,true))return {status:403,data:{ok:false,message:'Esta conta já está vinculada a outro computador.'}};license.lastSeenAt=new Date().toISOString();return {status:200,data:publicAccount(user,license,issueToken(user,'app'))}}
function profileByToken(db,token,input){const user=db.users.find(x=>x.tokenHash&&safe(x.tokenHash,sha(token||'')));if(!user)return {status:401,data:{ok:false,message:'Sessão inválida. Entre novamente.'}};const license=licenseFor(db,user),status=licenseStatus(license);if(status!=='active')return {status:403,data:{ok:false,message:'Ativação indisponível.'}};if(!hardwareAllowed(license,input,false))return {status:403,data:{ok:false,message:'Hardware não autorizado.'}};license.lastSeenAt=new Date().toISOString();return {status:200,data:publicAccount(user,license,null)}}
function publicCustomer(user,db){const l=licenseFor(db,user),status=licenseStatus(l),supportUnread=(db.supportMessages||[]).filter(x=>x.userId===user.id&&x.sender==='customer'&&!x.readByAdmin).length,partner=partnerForUser(db,user);return {id:user.id,username:user.username,email:user.email||'',createdAt:user.createdAt,plan:l&&l.plan||'none',status:status==='revoked'?'suspended':status,expiresAt:l&&l.expiresAt||null,hardwareBound:!!(l&&l.hardwareHash),hardwareBoundAt:l&&l.hardwareBoundAt||null,lastSeenAt:l&&l.lastSeenAt||null,premiumSupport:!!(l&&l.premiumSupport),supportUnread,partner:!!(partner&&partner.status==='active'),partnerSlug:partner&&partner.status==='active'?partner.slug:''}}
function supportMessagesFor(db,userId){return (db.supportMessages||[]).filter(x=>x.userId===userId).sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)).slice(-200)}
function addSupportMessage(db,userId,sender,text){const value=String(text||'').trim();if(!value||value.length>2000)return {status:400,data:{ok:false,message:'A mensagem precisa ter entre 1 e 2000 caracteres.'}};const message={id:crypto.randomUUID(),userId,sender,text:value,at:new Date().toISOString(),readByAdmin:sender==='admin',readByCustomer:sender==='customer'};db.supportMessages.push(message);db.events.unshift({at:message.at,type:'support_message',user:userId,sender});return {status:201,data:{ok:true,message}}}
function supportThreads(db){return db.users.map(user=>{const license=licenseFor(db,user);if(!license||!license.premiumSupport)return null;const messages=supportMessagesFor(db,user.id),last=messages[messages.length-1]||null,unread=messages.filter(x=>x.sender==='customer'&&!x.readByAdmin).length;return {userId:user.id,username:user.username,email:user.email||'',status:licenseStatus(license),premiumSupport:true,unread,lastMessage:last?last.text:'',lastAt:last?last.at:license.premiumSupportAt||license.activatedAt||user.createdAt}}).filter(Boolean).sort((a,b)=>Date.parse(b.lastAt||0)-Date.parse(a.lastAt||0))}
