function setCustomerPartner(db,user,active){if(!user)return {status:404,data:{ok:false,message:'Cliente não encontrado.'}};let partner=partnerForUser(db,user),now=new Date().toISOString();if(active){if(partner){partner.userId=user.id;partner.name=partner.name||user.username;partner.email=user.email||partner.email;partner.slug=partner.slug||uniquePartnerSlug(db,user.username,partner.id);partner.status='active';partner.updatedAt=now}else{partner={id:crypto.randomUUID(),userId:user.id,name:user.username,email:user.email||'',slug:uniquePartnerSlug(db,user.username),status:'active',commissionPercent:30,createdAt:now};db.partners.unshift(partner)}user.partnerId=partner.id;db.events.unshift({at:now,type:'customer_partner_enabled',user:user.id,partner:partner.id});return {status:200,data:{ok:true,customer:publicCustomer(user,db),partner:partnerView(partner,db)}}}if(partner){partner.status='suspended';partner.updatedAt=now;db.events.unshift({at:now,type:'customer_partner_disabled',user:user.id,partner:partner.id})}delete user.partnerId;return {status:200,data:{ok:true,customer:publicCustomer(user,db),partner:partner?partnerView(partner,db):null}}}
